import math
def usage(previous,current,seconds):
    if type(seconds) not in (int,float) or not math.isfinite(seconds) or seconds<=0 or not previous or previous.keys()!=current.keys():raise ValueError('same CPU set and positive aligned interval required')
    totals=dict(host=0,guest=0,idle=0,iowait=0,steal=0)
    for cpu in previous:
        delta={kind:{mode:value-previous[cpu][kind][mode] for mode,value in current[cpu][kind].items()} for kind in ('normal','guest')}
        if any(value<0 for group in delta.values() for value in group.values()):raise ValueError('counter reset')
        normal=delta['normal'];guest=sum(delta['guest'].values())
        executed=sum(normal[mode] for mode in ('user','nice','system','irq','softirq'))
        if guest>normal['user']+normal['nice']:raise ValueError('guest not contained in user/nice')
        totals['host']+=executed-guest;totals['guest']+=guest
        for mode in ('idle','iowait','steal'):totals[mode]+=normal[mode]
    capacity=seconds*len(previous)
    if not math.isclose(sum(totals.values()),capacity,rel_tol=.001,abs_tol=.001):raise ValueError('unaligned accounting interval')
    return {mode:value/capacity for mode,value in totals.items()}
